import{_ as a}from"./chunks/t265_intel_realsense_tracking_camera_photo_angle.CbPGUTXC.js";import{_ as s,c as i,o as t,al as l}from"./chunks/framework.D8UyiDWg.js";const m=JSON.parse('{"title":"Камера відстеження Intel® RealSense™ T265 (ВІО)","description":"","frontmatter":{},"headers":[],"relativePath":"uk/camera/camera_intel_realsense_t265_vio.md","filePath":"uk/camera/camera_intel_realsense_t265_vio.md"}'),n={name:"uk/camera/camera_intel_realsense_t265_vio.md"};function r(o,e,p,h,d,c){return t(),i("div",null,e[0]||(e[0]=[l('<h1 id="камера-відстеження-intel®-realsensetm-t265-віо" tabindex="-1">Камера відстеження Intel® RealSense™ T265 (ВІО) <a class="header-anchor" href="#камера-відстеження-intel®-realsensetm-t265-віо" aria-label="Permalink to &quot;Камера відстеження Intel® RealSense™ T265 (ВІО)&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This camera is discontinued.</p></div><p>The <em>Intel® RealSense™ Tracking Camera T265</em> provides odometry information that can be used for <a href="./../computer_vision/visual_inertial_odometry.html">VIO</a>, augmenting or replacing other positioning systems on PX4.</p><p>It is used in the <a href="./../computer_vision/visual_inertial_odometry.html#suggested-setup">Visual Inertial Odometry (VIO) &gt; Suggested Setup</a>.</p><p><img src="'+a+`" alt="Камера відстеження Intel® RealSense™ T265 - зображення збоку"></p><h2 id="де-купити" tabindex="-1">Де купити <a class="header-anchor" href="#де-купити" aria-label="Permalink to &quot;Де купити&quot;">​</a></h2><p>No longer available.</p><h2 id="інструкціі-з-налаштування" tabindex="-1">Інструкції з налаштування <a class="header-anchor" href="#інструкціі-з-налаштування" aria-label="Permalink to &quot;Інструкції з налаштування&quot;">​</a></h2><p>На загальному рівні:</p><ul><li>Для отримання необроблених даних з камери слід використовувати <a href="https://github.com/IntelRealSense/realsense-ros" target="_blank" rel="noreferrer">обгортку <code>realsense-ros</code></a>, надану компанією Intel.</li><li>Камеру слід встановити об&#39;єктивами спрямованими вниз (за замовчуванням). Не забудьте вказати орієнтацію камери, опублікувавши статичне перетворення між <code>base_link</code> та <code>camera_pose_frame</code> у файлі запуску ROS, наприклад:<div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">node</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pkg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tf&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;static_transform_publisher&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tf_baseLink_cameraPose&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    args</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0 0 0 0 1.5708 0 base_link camera_pose_frame 1000&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span></code></pre></div>Це - статичне перетворення, що пов&#39;язує систему відліку камери <code>camera_pose_frame</code> у ROS з системою відліку дрона <code>base_link</code> у MAVROS. <ul><li>перші три <code>args</code> вказують <em>перетворення</em> x,y,z у метрах від центру контролера польоту до камери. Наприклад, якщо камера знаходиться на відстані 10 см від контролера і на висоті 4 см, перші три числа будуть: [0.1, 0, 0.04,...]</li><li>наступні три <code>args</code> вказують обертання в радіанах (рискання, тангаж, крен). Тому <code>[... 0, 1.5708, 0]</code> означає нахил вниз на 90° (обернений до землі). Обернений вперед буде [... 0 0 0].</li></ul></li><li>Камера чутлива до високочастотних вібрацій! Вона повинна бути змонтована з м&#39;яким кріпленням, наприклад з піною для віброізоляції.</li></ul>`,10)]))}const u=s(n,[["render",r]]);export{m as __pageData,u as default};
